public static void SetOverviewImage(TFMPageID _pageId, str _overviewImage)
{
    TFMPageImage imgTable;

    ttsbegin;
    imgTable = TFMPageImage::Find(_pageId,true);

    imgTable.PageID = _pageId;
    imgTable.OverviewImage = _overviewImage;
    imgTable.write();
    ttscommit;
}

	public static TFMPageImage Find (TFMPageID _pageId, boolean _selectforUpdate = false)
    {
        TFMPageImage imgTable;

        imgTable.selectForUpdate(_selectForUpdate);
        select firstonly imgTable where imgTable.pageId == _pageId;

        return imgTable;
    }

public static void removePageImage(TFMPageID _pageId)
{
    TFMPageImage imgTable;
    str cacheId = formstr(TFMPageOverview) + TFMPageOverviewFormClass::cacheTimeStamp() + strLwr(curExt());
    System.Runtime.Caching.ObjectCache memCache = System.Runtime.Caching.MemoryCache::Default;

    Map	 pagePreviews = memCache.Get(cacheId);
    pagePreviews = new Map(Types::String, Types::String);
    memCache.Add(cacheId, pagePreviews, new System.Runtime.Caching.CacheItemPolicy());

    ttsbegin;
    delete_from imgTable where imgTable.pageId == _pageId;
    ttscommit;
}
